import {agentRegistry,observationView,observe,analyze} from './agents.mjs';
import {startSession,askTopic,administer,finish,makeReport,reportText} from './core.mjs';
const $=id=>document.getElementById(id);
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
let data,session,report;
function error(e){$('error').textContent=e.message;$('error').hidden=false;}
function show(id){if(id==='review' && session)renderAgents();document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.panel===id));$('error').hidden=true;}
function drawTurn(t){const e=node('div',undefined,'exchange');e.append(node('div',`${t.id} · LEARNER`,'speaker'),node('p',t.question,'question'),node('div','ALEX · SCRIPTED RESPONSE','speaker'),node('p',t.reply,'answer'));$('conversation').append(e);$('turnCount').textContent=`${session.turns.length} ${session.turns.length===1?'exchange':'exchanges'}`;$('conversation').scrollTop=$('conversation').scrollHeight;}
function ask(id){$('error').hidden=true;if(!session.turns.length)$('conversation').replaceChildren();const t=askTopic(session,data.case,id);drawTurn(t);renderAgents();return {turnId:t.id,response:t.reply};}
function renderReport(){const r=report;const box=$('reportContent');box.replaceChildren();box.append(node('p',`${r.coverage.covered.length} of ${r.coverage.total} authored topic areas opened. This is a coverage summary, not a competence score.`));const topics=node('div');r.coverage.covered.forEach(d=>topics.append(node('span',d,'tag')));box.append(topics,node('h3','Areas to explore further'),node('p',r.coverage.missing.join(', ')||'All authored topics were opened. Depth, question quality and interpretation still need review.'),node('h3','Assessment'),node('p',r.assessment?`Simulated GAD-7: ${r.assessment.total}/21, ${r.assessment.band.toLowerCase()} anxiety symptoms. This does not establish a diagnosis.`:'Not administered. No questionnaire result is disclosed.'),node('h3','Your reasoning'));Object.entries(r.reasoning).forEach(([k,v])=>{box.append(node('strong',k.charAt(0).toUpperCase()+k.slice(1)),node('p',v,'reasoningText'));});box.append(node('h3','Feedback ratings'));r.ratings.forEach(x=>{const e=node('div',undefined,'datum');e.append(node('strong',`${x.name}: NR`),node('span',x.reason));box.append(e);});box.append(node('h3','Conversation evidence'));r.evidence.forEach(e=>{const p=node('div',undefined,'evidence');p.append(node('strong',`${e.turnId} · ${e.factIds.join(', ')}`),node('p',e.question),node('p',e.quote));box.append(p);});box.append(node('p','Review the evidence with your supervisor. Missing topics are learning opportunities; the case answer alone does not establish interview competence.','small'));$('download').hidden=false;}
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>show(t.dataset.panel));
$('ask').onclick=()=>{try{ask($('topic').value);}catch(e){error(e);}};
$('topic').onchange=()=>{$('questionPreview').textContent=data.case.facts.find(f=>f.id===$('topic').value).question;};
$('administer').onclick=()=>{try{const a=administer(session,data.case,$('rationale').value,$('explained').checked);$('error').hidden=true;const box=$('assessmentResult');box.replaceChildren(node('div',`${a.total} / 21`,'resultNumber'),node('p',`${a.band} anxiety symptoms · fictional client result`),node('p',`Item responses: ${a.values.join(', ')}. Functional difficulty: ${a.difficulty} (not included in score).`),node('p','Use alongside interview evidence. The simulated client is not a validated test respondent.'));box.append(node('p',data.case.gad7.instruction));data.case.gad7.items.forEach((item,i)=>{const row=node('div',undefined,'datum');row.append(node('strong',`${i+1}. ${item}`),node('span',`${data.case.gad7.response_labels[a.values[i]]} (${a.values[i]})`));box.append(row);});box.append(node('p',data.case.gad7.attribution,'small'));}catch(e){error(e);}};
$('reasoningForm').onsubmit=e=>{e.preventDefault();try{report=finish(session,Object.fromEntries(new FormData(e.target)));renderReport();$('ask').disabled=true;$('administer').disabled=true;$('status').textContent='Session ended · case A01 v0.1.0 · review pending';show('report');}catch(err){error(err);}};
$('download').onclick=()=>{const b=new Blob([reportText(report)],{type:'text/plain;charset=utf-8'}),u=URL.createObjectURL(b),a=node('a');a.href=u;a.download='psych-interview-debrief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
$('reset').onclick=()=>{if(session.turns.length&&!confirm('Clear this rehearsal and its unsaved report?'))return;session=startSession(data.case);report=null;$('conversation').replaceChildren(node('p','Start with what brings Alex here today.','empty'));$('turnCount').textContent='0 exchanges';$('assessmentResult').replaceChildren();$('rationale').value='';$('explained').checked=false;$('reasoningForm').reset();$('reportContent').replaceChildren(node('p','Finish your reasoning to create a debrief.','empty'));$('download').hidden=true;$('ask').disabled=false;$('administer').disabled=false;$('status').textContent='Case A01 v0.1.0 · scripted rehearsal · review pending';renderAgents();show('interview');};
async function init(){try{const res=await fetch('data.json');if(!res.ok)throw new Error('Case could not be loaded. Please reload.');data=await res.json();session=startSession(data.case);$('referral').textContent=data.case.referral;data.case.facts.forEach(f=>{const o=node('option',f.label);o.value=f.id;$('topic').append(o);});$('topic').onchange();$('caseGuide').append(node('p',data.case.background),node('p',data.case.working_formulation),node('p',`Unknowns: ${data.case.unknowns.join('; ')}`));data.rubric.forEach(r=>{const ul=node('ul');r.anchors.forEach(a=>ul.append(node('li',a)));$('rubric').append(node('h3',r.name),ul);});data.sources.forEach(s=>{const p=node('p'),a=node('a',`${s.id} · ${s.title}`);a.href=s.url;a.target='_blank';a.rel='noreferrer';p.append(a,node('br'),node('span',`${s.publisher}. ${s.version}. ${s.use} ${s.rights}`));$('sources').append(p);});$('status').textContent='Case A01 v0.1.0 · scripted rehearsal · review pending';renderAgents();registerTools();}catch(e){error(e);$('ask').disabled=true;$('administer').disabled=true;$('status').textContent='Case unavailable';}}
function registerTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const defs=[{name:'read_rehearsal_state',description:'Read scripted rehearsal state without revealing unasked case facts.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mode:'scripted',turns:session.turns.length,ended:!!session.reasoning,assessmentAdministered:!!session.assessment})},{name:'ask_authored_topic',description:'Add one authored question and scripted client response to this rehearsal.',inputSchema:{type:'object',properties:{topicId:{type:'string',enum:data.case.facts.map(f=>f.id)}},required:['topicId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.topicId!=='string')throw new Error('topicId is required');const r=ask(input.topicId);show('interview');return r;}}];defs.forEach(d=>{try{Promise.resolve(ctx.registerTool(d,{signal:lifecycle.signal})).catch(()=>{});}catch{}});}
init();

function renderAgents(){
  const box=$('agentInspector');box.replaceChildren();
  box.append(node('p','Deterministic responsibilities over the authored case. No live model calls or validated psychological dynamics.'));
  for(const agent of agentRegistry){const row=node('div',undefined,'datum');row.append(node('strong',agent.id),node('span',agent.role));box.append(row);}
  const trace=session.agentTraces.at(-1);
  box.append(node('h3','Latest interview trace'));
  if(trace){
    box.append(node('p',`${trace.turnId} · engine ${trace.version}`));
    for(const step of trace.steps){const detail=node('details');detail.append(node('summary',step.agent),node('pre',JSON.stringify(step.output,null,2),'agentData'));box.append(detail);}
  }else box.append(node('p','Ask a topic to inspect the agents.'));
  const view=observationView(session);
  box.append(node('h3','Observer: disclosed evidence'),node('pre',JSON.stringify(observe(view),null,2),'agentData'),node('h3','Analyst: interview counts'),node('pre',JSON.stringify(analyze(view),null,2),'agentData'));
}
